grid=[[0]*15 for _ in range(15)]
rows={2:[2,2,2,0,2,2]+[0]*9,3:[0]*6+[5,5,0]+[5]*6,6:[3,3,3,0,3,3,3]+[0]*8,8:[0]*6+[9,9,0]+[9]*6,11:[4,4,4,0,4,4,4,4,0]+[4]*6}
# assign input rows
for r,line in rows.items(): grid[r]=line.copy()
grid[13][3]=6;grid[14][3]=6;grid[14][8]=8
# fill marker gaps per stripe where adjacent values equal
cols=[3,8]
for r,line in rows.items():
    for c in cols:
        if line[c]==0 and c>0 and c<14 and line[c-1]==line[c+1]!=0:
            grid[r][c]=line[c-1]
# projection: each stripe's color at marker column when newly filled; upwards until previous stripe having nonzero at col
for r,line in rows.items():
    for c in cols:
        val=grid[r][c]
        if not val: continue
        prev=[rr for rr in rows if rr<r and grid[rr][c]!=0]
        stop=max(prev) if prev else -1
        for rr in range(stop+1,r):
            if grid[rr][c]==0: grid[rr][c]=val
print('\n'.join(' '.join(map(str,row)) for row in grid))
